content.text:
I found three faults. Two are slow application methods, in food-service and route-plan-service. The third is ui-dashboard aborting its calls to consign-service. Several other services' tail latency is downstream of these.

```json
{
  "root_causes": [
    {
      "service": "ts-food-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, attr_status_code, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-food-service' AND span_name IN ('FoodOrderRepository.save','POST /api/v1/foodservice/orders') GROUP BY ALL ORDER BY span_name, p", "claim": "FoodOrderRepository.save p95 rose from about 5 ms to about 2.1 s while its child spans stayed in the low milliseconds."},
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-food-service' AND span_name IN ('FoodOrderRepository.save','Transaction.commit','Session.merge foodsearch.entity.FoodOrder','INSERT ts.food_order') GROUP BY ALL ORDER BY span_name, p", "claim": "Database-side child spans of food save stayed flat, so the extra time sits inside the food method itself."}
      ]
    },
    {
      "service": "ts-route-plan-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, attr_span_kind kind, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50, round(approx_quantile(duration,0.95)/1e6,1) p95 FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-route-plan-service' AND attr_span_kind='Server' GROUP BY ALL HAVING count(*)>=5 ORDER BY service_name, span_name, p", "claim": "Route-plan quickestRoute p95 rose from about 694 ms to 2.6 s, with median nearly unchanged."},
        {"kind": "trace", "sql": "WITH t AS (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND span_name='POST /api/v1/routeplanservice/routePlan/quickestRoute' AND duration>1500000000 LIMIT 1) SELECT a.service_name, a.span_name, a.attr_span_kind kind, round(a.duration/1e6,1) ms FROM abnormal_traces a JOIN t USING(trace_id) ORDER BY a.time", "claim": "In a slow quickestRoute trace, about 2.6 s is spent inside route-plan itself; its only client call to travel took 151 ms."}
      ]
    },
    {
      "service": "ts-ui-dashboard",
      "fault_kind": "http_aborted",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, attr_span_kind kind, attr_status_code st, attr_http_response_status_code code, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50, round(approx_quantile(duration,0.95)/1e6,1) p95 FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE span_name LIKE '%consign%' AND span_name LIKE '%account%' GROUP BY ALL ORDER BY service_name, p, kind", "claim": "ui-dashboard returned 503 for 113 consign account requests, while consign's own server spans stayed 200 and only 49 arrived."},
        {"kind": "log", "sql": "SELECT service_name, level, substr(message,1,300) m, count(*) n FROM abnormal_logs WHERE service_name='ts-ui-dashboard' AND level <> 'INFO' GROUP BY ALL ORDER BY n DESC LIMIT 10", "claim": "ui-dashboard logs a 503 handled-request error on the consign account path, with upstream service time about 489 ms."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-food-service",
      "to": "ts-preserve-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, attr_span_kind kind, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50, round(approx_quantile(duration,0.95)/1e6,1) p95 FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE (service_name='ts-food-service' AND span_name='POST /api/v1/foodservice/orders') OR (service_name='ts-preserve-service' AND attr_span_kind='Client') GROUP BY ALL ORDER BY service_name, span_name, p", "claim": "Food orders server p95 rose to 2.1 s, and preserve's outgoing client calls p95 rose from 168 ms to 275 ms."}
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, attr_span_kind kind, attr_http_response_status_code code, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50, round(approx_quantile(duration,0.95)/1e6,1) p95 FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND span_name ILIKE '%preserve%' GROUP BY ALL ORDER BY span_name, p", "claim": "ui-dashboard's preserve endpoint p95 rose from 800 ms to 1538 ms, status 200 throughout."}
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, attr_span_kind kind, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95 FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY ALL HAVING count(*)>=5 ORDER BY span_name, p", "claim": "Travel-plan quickest and cheapest server p95 rose sharply, consistent with waiting on route-plan's slow quickestRoute calls."}
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95 FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND span_name ILIKE '%travelplan%' GROUP BY ALL ORDER BY span_name, p", "claim": "ui-dashboard travelPlan endpoints show a slower p95 in the abnormal period, following travel-plan's slow calls."}
      ]
    }
  ]
}
```

